package com.lankawings.servlet;
import com.lankawings.dao.*;import com.lankawings.model.*;import com.lankawings.util.Req;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/reservation-confirmed") public class ReservationConfirmationServlet extends HttpServlet{@Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String pnr=Req.param(r,"pnr").strip();Booking b=new BookingDAO().findByPnr(pnr);if(b==null||b.getUserId()!=Req.uid(r)){s.sendError(404);return;}r.setAttribute("booking",b);r.setAttribute("ticket",new TicketDAO().findByBooking(b.getBookingId()));}catch(Exception e){Req.error(r,e);}r.getRequestDispatcher("/WEB-INF/views/reservation-confirmed.jsp").forward(r,s);}}
